B.BU=new A.c(B.awA,[B.Fu,B.Fa,B.fq,B.fs,B.EA,B.Ez,B.Ey,B.EB,B.Fi,B.Fg,B.Fh,B.Ea,B.E7,B.E0,B.E5,B.E6,B.FK,B.FJ,B.G4,B.G8,B.G5,B.G3,B.G7,B.G2,B.G6,B.er,B.Eb,B.ET,B.fo,B.i9,B.Fn,B.Fd,B.Fc,B.Ev,B.DZ,B.DQ,B.DR,B.DS,B.DT,B.DU,B.DV,B.DW,B.DX,B.DY,B.FI,B.FT,B.Ew,B.E_,B.E4,B.p5,B.p5,B.Ee,B.En,B.Eo,B.Ep,B.EW,B.EX,B.EY,B.EZ,B.F_,B.F0,B.F1,B.Ef,B.F2,B.F3,B.F4,B.F5,B.F6,B.Eg,B.Eh,B.Ei,B.Ej,B.Ek,B.El,B.Em,B.Ff,B.i8,B.CQ,B.CW,B.D4,B.D5,B.D6,B.D7,B.D8,B.D9,B.Da,B.CX,B.CY,B.CZ,B.D_,B.D0,B.D1,B.D2,B.D3,B.Db,B.Dc,B.Dd,B.De,B.Df,B.Dg,B.Dh,B.Di,B.Dj,B.Dk,B.Dl,B.Dm,B.Dn,B.Do,B.Dp,B.F8,B.Et,B.CO,B.Es,B.ES,B.Fk,B.Fm,B.Fl,B.Dq,B.Dr,B.Ds,B.Dt,B.Du,B.Dv,B.Dw,B.Dx,B.Dy,B.Dz,B.DA,B.DB,B.DC,B.DD,B.DE,B.DF,B.DG,B.DH,B.DI,B.DJ,B.DK,B.DL,B.DM,B.DN,B.DO,B.DP,B.Gd,B.Fp,B.Fq,B.Fr,B.Fs,B.Ft,B.FY,B.FX,B.G1,B.FZ,B.FW,B.G0,B.Gb,B.Ga,B.Gc,B.FO,B.FM,B.FL,B.FU,B.FN,B.FP,B.FV,B.FS,B.FQ,B.FR,B.fr,B.ib,B.CV,B.E3,B.Fo,B.kN,B.EQ,B.EH,B.EI,B.EJ,B.EK,B.EL,B.EM,B.EN,B.EO,B.EP,B.EF,B.Fy,B.FE,B.FF,B.Fj,B.ER,B.EC,B.EG,B.EV,B.FC,B.FB,B.FA,B.Fz,B.FD,B.ED,B.Fw,B.Fx,B.EE,B.F7,B.Ex,B.Eu,B.Fe,B.Er,B.Ec,B.EU,B.Eq,B.CU,B.Fv,B.E9,B.CS,B.kM,B.F9,B.G_,B.E8,B.fp,B.ia,B.Ge,B.Ed,B.FG,B.E2,B.CP,B.CR,B.E1,B.CT,B.Fb,B.FH,B.G9],A.aa("c<h,y>"))
B.axv={[u.Y]:0,[u.a2]:1,"\uad6c\ub984 \uc544\ub798\ub85c \ubb34\ub108\uc9c4 \uc9d1\uc774 \ubcf4\uc778\ub2e4. \uc4f8 \ub9cc\ud55c \uac8c \ub0a8\uc544 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4.":2,"\uadf8\ub7f0\ub370 \uc774\uc0c1\ud558\ub2e4. \uc774 \ub79c\ud134 \ube5b\uc774 \ub2ff\uc740 \uacf3\ub9cc, \uc7ac\uac00 \ub179\ub4ef\uc774 \uac77\ud78c\ub2e4.":3,"\ubb34\ub108\uc9c4 \uc9d1\uc744 \ub450\ub4dc\ub824 \ub4a4\uc9c0\uba74 \ubaa9\uc7ac\uac00, \ud3d0\ucc28\uc5d0\uc11c\ub294 \uace0\ucca0\uc774 \ub098\uc628\ub2e4.":4,[u.W]:5,"\uc190\uc774 \ub2e4 \uae4c\uc84c\uc9c0\ub9cc \ubaa9\uc7ac\uac00 \uc81c\ubc95 \uc313\uc600\ub2e4. \uc774\uc81c \ubb54\uac00 \ub9cc\ub4e4 \uc218 \uc788\uaca0\ub2e4.":6,[u.a8]:7,[u.cM]:8,"\ud0d5, \ud0d5. \ub9dd\uce58 \uc18c\ub9ac. \uc624\ub79c\ub9cc\uc5d0 \ub4e3\ub294 \uc0b4\uc544 \uc788\ub294 \uc18c\ub9ac\ub2e4.":9,"\ud1b5\uc870\ub9bc\uc740 \uc5b8\uc820\uac00 \ub5a8\uc5b4\uc9c4\ub2e4. \ud759\uc744 \ubaa8\uc544 \ud143\ubc2d \uc0c1\uc790\ub97c \uc9dc \ub450\uc790.":10,"\ucc9c\uc740 \ubb34\ub108\uc9c4 \uc9d1\uc774\ub098 \ud138\ub9b0 \uc0c1\uc810\uc744 \ub4a4\uc9c0\uba74 \ub098\uc628\ub2e4.":11,"\uc7ac \uc544\ub798 \ud759\uc774 \uc544\uc9c1 \ucd95\ucd95\ud588\ub2e4. \ub545\uc740 \uc0b4\uc544 \uc788\ub2e4.":12,"\ubc24\uc0c8 \uc800\ucabd \uad6c\ub984 \uc18d\uc5d0\uc11c \ud770 \ube5b\uc774 \uae5c\ube61\uc600\ub2e4. \uc190\uc804\ub4f1 \uc2e0\ud638\ub2e4.":13,"\ub204\uad70\uac00 \uc0b4\uc544 \uc788\ub2e4. \uadf8\ucabd\uc73c\ub85c \uae38\uc744 \uc5f4\uc790.":14,[u.R]:15,"\ud5c8, \ubd88\ube5b \ubcf4\uace0 \ubc84\ud17c\uc9c0. \uc774 \uadfc\ucc98\uc5d0 \uc0b0 \uc0ac\ub78c\uc774 \uc788\uc744 \uc904\uc740 \ubab0\ub790\ub124.":16,"\uc774\uc81c \ud63c\uc790\uac00 \uc544\ub2c8\ub2e4.":17,"\uac00\ub9cc\uc788\uc73c\uba74 \ub354 \uc8fd\uaca0\uc5b4. \uc791\uc5c5\ub300\ub4e0 \ud143\ubc2d\uc774\ub4e0 \uc77c \uc880 \uc8fc\uac8c.":18,"\uc190\uc5d0 \ub9de\ub294 \uc77c\uc774\uba74 \ub450 \ubc30\ub294 \ud574\ub0b4\uc9c0. \ub09c \uc5f0\uc7a5 \ub9cc\uc9c0\ub294 \uac8c \uc81c\uc77c \ud3b8\ud558\uace0.":19,"\uc77c\uc744 \ud558\ub2c8\uae4c \uc880 \uc0b4 \uac83 \uac19\uad6c\uba3c.":20,"\ub098\ub3c4 \uc798\ud558\ub294 \uac8c \ud558\ub098 \uc788\uc9c0. \ud544\uc694\ud560 \ub54c \ubd80\ub974\ub77c\uace0.":21,"\uc5b4\ub54c, \uc774 \ub299\uc740\uc774 \uc544\uc9c1 \uc4f8 \ub9cc\ud558\uc9c0?":22,"\uace0\ucca0\uc744 \ub450\ub4dc\ub824 \ud3b4\uba74 \ucca0\ud310\uc774 \ub3fc. \uc258\ud130\ub97c \ud0a4\uc6b0\ub824\uba74 \uc774\uac8c \uaf2d \uc788\uc5b4\uc57c \ud558\uace0.":23,"\ubc18\ub4ef\ud558\ub124. \uc774\uac78\ub85c \ubcbd \uc138\uc6b0\uba74 \ub418\uaca0\uc5b4.":24,[u.cf]:25,"\ubcbd\uc774 \uc0dd\uacbc\ub2e4. \ubc14\ub78c \uc18c\ub9ac\uac00 \ud55c \uacb9 \uba40\uc5b4\uc84c\ub2e4.":26,"\uc258\ud130\uac00 \ucee4\uc9c0\uc790 \ub79c\ud134 \ube5b\ub3c4 \ub354 \uba40\ub9ac \ub2ff\ub294\ub2e4.":27,"\ud558\ub298 \uc0c9 \uc880 \ubd10. \ud574 \uc9c0\uba74 \uc7ac\ud3ed\ud48d\uc774 \uc628\ub2e4.":28,"\ubd89\uac8c \ubc88\uc9c0\ub294 \uc7ac\ub97c \uc81c\ub54c \uac77\uc5b4\ub0b4\uc57c \ud574. \uc548 \uadf8\ub7ec\uba74 \ubc1d\ud78c \ub545 \ub3c4\ub85c \ube8f\uaca8.":29,"\ubc84\ud17c\ub2e4! \uc774 \uadfc\ucc98\uc5d0\uc11c \ubc24\uc744 \ub118\uae34 \ubd88\ube5b\uc740 \uc6b0\ub9ac\ubfd0\uc77c \uac70\uc57c.":30,[u.o]:31,"\uc7ac\uac00 \uc790\uafb8 \uc258\ud130 \ucabd\uc744 \ub178\ub824. \ub098\ubb34 \uc6b8\ud0c0\ub9ac\ub77c\ub3c4 \ub458\ub7ec \ub450\uc790\uace0.":32,"\ubc27\uc904\uc740 \uc791\uc5c5\ub300\uc5d0\uc11c \ucc9c\uc744 \uaf2c\uc544 \ub9cc\ub4e4\uba74 \ub3fc.":33,"\uc6b8\ud0c0\ub9ac \ub108\uba38\ub85c \uc7ac\uac00 \uc313\uc600\ub2e4 \ud769\uc5b4\uc9c4\ub2e4. \uc624\ub298 \ubc24\uc740 \uc870\uae08 \ub35c \ubb34\uc12d\ub2e4.":34,"\uc26c\uc9c0 \uc54a\uace0 \ub450\ub4dc\ub9ac\uba74 \ub79c\ud134\uc774 \ud65c\ud65c \ud0c0\uc624\ub978\ub2e4.":35,"\ubd88\uaf43\uc774 \ud070 \ub3d9\uc548\uc5d0\ub294 \uad6c\ub984\ub3c4 \ud3d0\ud5c8\ub3c4 \ub450 \ubc30\ub85c \ud138\ub9b0\ub2e4.":36,"\ud55c\uc21c\uac04, \uc628 \ub3d9\ub124\uac00 \ub300\ub0ae\ucc98\ub7fc \ubc1d\uc558\ub2e4.":37,[u.b]:38,"\uc4f8 \ub9cc\ud55c \uac8c \ubc8c\uc368 \uba87 \uac1c \uad74\ub7ec \ub4e4\uc5b4\uc654\uad6c\uba3c.":39,"\uc0ac\ub78c\uc774 \ubaa8\uc774\uba74 \ubd80\ud0c1\ub3c4 \uc0dd\uae34\ub2e4. \ub9d0\ud48d\uc120\uc774 \ub728\uba74 \uadc0\ub97c \uae30\uc6b8\uc774\uc790.":40,"\uc791\uc740 \ubd80\ud0c1 \ud558\ub098 \ub4e4\uc5b4\uc92c\uc744 \ubfd0\uc778\ub370, \uc258\ud130 \uacf5\uae30\uac00 \ub2ec\ub77c\uc84c\ub2e4.":41,"\ub9e8\uc190\uc73c\ub85c \ud3d0\ud5c8 \ub4a4\uc9c0\ub2e4\uac04 \uc190\uc774 \ub0a8\uc544\ub098\uc9c8 \uc54a\uc544.":42,[u.bY]:43,"\uc190\uc5d0 \ub531 \ub9de\ub124. \uc774\uc81c \uc880 \uc77c\ud560 \ub9db\uc774 \ub09c\ub2e4.":44,"\ud310\uc7a3\uc9d1 \ubd88\ube5b\uc774 \uba40\ub9ac\uc11c\ub3c4 \ubcf4\uc774\ub294 \ubaa8\uc591\uc774\ub2e4. \ub204\uad70\uac00 \uc774\ucabd\uc744 \uc0b4\ud53c\uace0 \uc788\ub2e4.":45,"\uc14b\uc774 \ub418\uc790 \uc2dd\ud0c1\uc5d0 \uc218\ub2e4\uac00 \uc0dd\uacbc\ub2e4.":46,"\uae38\uac00\uc5d0 \ucee8\ud14c\uc774\ub108\uac00 \uad74\ub7ec\ub2e4\ub2c8\ub354\ub77c\uace0. \ucca0\ud310 \ub367\ub300\uba74 \ud2bc\ud2bc\ud55c \uc258\ud130\uac00 \ub418\uc9c0.":47,"\ucee8\ud14c\uc774\ub108\ub97c \uc313\uc544 \uc62c\ub838\ub2e4. \uc774\uc81c \uc5ec\uae30\uac00 \uc6b0\ub9ac \ub3d9\ub124\ub2e4.":48,[u.cX]:49,"\ub2e4\uc774\uc5bc\uc744 \ub3cc\ub9ac\uba74 \uba3c \uacf3\uc758 \uc2e0\ud638\uac00 \uc7a1\ud78c\ub2e4. \uac00\ub054\uc740\u2026 \uc0ac\ub78c \ubaa9\uc18c\ub9ac\ub3c4.":50,[u.b7]:51,"\ub4f1\ubd88 \uacc4\ud68d? \ucc98\uc74c \ub4e3\ub294 \ub9d0\uc774\ub2e4. \uc774 \ub79c\ud134\uacfc \ubb34\uc2a8 \uc0c1\uad00\uc774 \uc788\uc744\uae4c.":52,[u.y]:53,"\ubaa9\uc18c\ub9ac\ub294 \uc6b0\ub9ac \ubd88\ube5b\uc744 \ubd24\ub2e4\uace0 \ud588\ub2e4. \uace7 \ucc3e\uc544\uac00\uaca0\ub2e4\uace0.":54,[u.v]:55,"\uc774 \ub77c\ub514\uc624, \uc81c\uac00 \uc190\ubd10 \ub4dc\ub9b4\uac8c\uc694. \uc778\ub450\ub9cc \uc788\uc73c\uba74 \uae08\ubc29\uc774\uc5d0\uc694.":56,[u.m]:57,"\uadf8\ub0a0 \ubc24, \uc258\ud130\uc5d0 \ucc98\uc74c\uc73c\ub85c \uc74c\uc545\uc774 \ud758\ub800\ub2e4.":58,"\uc774 \uadfc\ucc98\ub294 \uac70\uc758 \ub2e4 \ud138\uc5c8\uc5b4. \uba40\ub9ac \ub2e4\ub140\uc624\uba74 \ubd80\ud488\uc774\ub791 \uc5f0\ub8cc\uac00 \uc788\uc744 \uac70\uc57c.":59,"\ub2e4\ub140\uc654\ub124. \uae38 \uc704\uc5d0\uc11c \ubcc4\uac78 \ub2e4 \ubd24\uc5b4.":60,"\uad6c\ub984 \uc704\ub85c \uc61b \uac74\ubb3c\ub4e4\uc758 \uadf8\ub9bc\uc790\uac00 \ubcf4\uc778\ub2e4. \ud559\uad50, \uae09\uc218\ud0d1, \uc8fc\uc720\uc18c\u2026":61,[u.H]:62,"\ubb34\ub108\uc84c\ub358 \uac74\ubb3c\uc5d0 \ub2e4\uc2dc \ubd88\uc774 \ub4e4\uc5b4\uc654\ub2e4. \ud3d0\ud5c8\uac00 \ub3d9\ub124\ub85c \ub3cc\uc544\uc624\uace0 \uc788\ub2e4.":63,"\ubd88\ube5b\uc774 \ucee4\uc9c8\uc218\ub85d \uc0ac\ub78c\ub4e4\uc774 \ucc3e\uc544\uc628\ub2e4. \uad6c\ub984 \uc18d\uc5d0\ub294 \uc544\uc9c1 \uc2e0\ud638\uac00 \ub0a8\uc544 \uc788\ub2e4.":64,"\ub2e4\uc12f \uc0ac\ub78c. \uc2dd\ud0c1\uc774 \uc881\uc544\uc84c\ub2e4. \uadf8\uac8c \uc88b\ub2e4.":65,[u.at]:66,[u.O]:67,"\uc9c0\ud558 2\uce35. \uc5b4\ub460\uc774 \ud6e8\uc52c \uc9d9\uc5c8\uc9c0\ub9cc, \uadf8\ub9cc\ud07c \ub0a8\uc740 \uac83\ub3c4 \ub9ce\uc558\ub2e4.":68,"\ub354 \uae4a\uc740 \ub370\uc5d4 \uba3c\uc800 \ud53c\ub09c \uac04 \uc0ac\ub78c\ub4e4 \uc9d0\ub3c4 \ub0a8\uc544 \uc788\uc744\uc9c0 \ubab0\ub77c.":69,"\uc5f0\ub8cc\ub9cc \uc788\uc73c\uba74 \ubc1c\uc804\uae30\ub294 \ub0b4\uac00 \ub3cc\ub824 \ubcf4\uc9c0. \uc804\uad6c\uac00 \ub2e4\uc2dc \ucf1c\uc9c0\ub294 \uac70\uc57c.":70,"\uc804\uad6c\uac00 \uae5c\ube61\uc774\ub2e4 \ucf1c\uc84c\ub2e4. \ub204\uad70\uac00 \ubc15\uc218\ub97c \ucce4\ub2e4.":71,[u.aT]:72,"\ub354 \ub0b4\ub824\uac00 \ubcf4\uba74 \ubb54\uac00 \uc54c \uc218 \uc788\uaca0\uc9c0.":73,"\uc816\uc740 \uc791\uc5c5 \uc77c\uc9c0\ub9c8\ub2e4 \uac19\uc740 \ub9d0\uc774 \uc801\ud600 \uc788\uc5c8\ub2e4. \ub4f1\ubd88 \uacc4\ud68d.":74,[u.c2]:75,"\ubc1c\uc804\uc18c \ubc29\ud5a5, \uac00\uc7a5 \uba3c \uad6c\ub984 \uc18d\uc5d0\uc11c \uaddc\uce59\uc801\uc778 \ubd88\ube5b\uc774 \uae5c\ube61\uc778\ub2e4.":76,"\ub204\uad70\uac00 \uc77c\ubd80\ub7ec \uadf8 \ubc15\uc790\ub85c \uc2e0\ud638\ub97c \ubcf4\ub0b4\uace0 \uc788\ub2e4.":77,"\u2026\ubc1c\uc804\uc18c \uc5f0\uad6c\uc6d0 \uc624\uc7ac\ud601\uc774\uc5d0\uc694. \uc0b4\ub824 \uc918\uc11c \uace0\ub9c8\uc6cc\uc694.":78,"\uadf8\uc758 \ub208\uc774 \ub0b4 \ub79c\ud134\uc5d0 \ud55c\ucc38 \uba38\ubb3c\ub800\ub2e4. \ubb34\uc5b8\uac00 \ub9d0\ud558\ub824\ub2e4 \uadf8\ub9cc\ub450\uc5c8\ub2e4.":79,"\uadf8\ub294 \uc9c0\ud558 \uae30\ub85d \uc774\uc57c\uae30\uac00 \ub098\uc624\uc790 \ub208\uc744 \ud53c\ud588\ub2e4.":80,[u.q]:81,[u.k]:82,"\u2026\uadf8\uac78 \uc65c \uc774\uc81c\uc57c \ub9d0\ud558\ub098?":83,[u.F]:84,[u.B]:85,[u.a]:86,"\uadf8\ub0a0 \ubc24, \uc544\ubb34\ub3c4 \uc27d\uac8c \uc7a0\ub4e4\uc9c0 \ubabb\ud588\ub2e4.":87,"\uadf8\ub798\ub3c4 \uc544\uce68\uc5d4 \ubaa8\ub450 \uac19\uc740 \uc2dd\ud0c1\uc5d0 \uc549\uc558\ub2e4.":88,"\uc774\ub9cc\ud558\uba74 \uc694\uc0c8\ub85c \uc62c\ub9b4 \ub54c\uac00 \ub410\uc5b4. \ubd80\ud488\uc774\ub791 \uc5f0\ub8cc\ub9cc \ub109\ub109\ud558\uba74 \ub3fc.":89,"\ub9dd\ub8e8\uc5d0 \uc62c\ub77c\uc11c\ub2c8 \uc9c0\ud3c9\uc120 \ub05d\uc5d0 \ubc1c\uc804\uc18c \uad74\ub69d\uc774 \ubcf4\uc600\ub2e4.":90,[u.bl]:91,[u.cJ]:92,"\uc0c8\ubcbd\uc774 \uc654\ub2e4. \uc258\ud130\ub294 \ubb34\ub108\uc9c0\uc9c0 \uc54a\uc558\ub2e4.":93,"\uc6b0\ub9ac, \uc81c\ubc95 \uac15\ud574\uc84c\uad6c\uba3c.":94,"\u2026\ucc3d\uace0 \ud138\ub9b0 \uac83\ub9cc \ube7c\uba74 \ub9d0\uc774\uc57c.":95,"\uc694\uc998 \uc7ac \uad34\ubb3c\uc774 \uc810\uc810 \ucee4\uc838. \ub098\ubb34 \uc6b8\ud0c0\ub9ac\ub85c\ub294 \uc5b4\ub9bc\uc5c6\uc5b4.":96,"\ubaa8\ub798\uc8fc\uba38\ub2c8\ub97c \uc313\uc544 \uc62c\ub9ac\uc790 \uc258\ud130\uac00 \ud55c\uacb0 \ub2e8\ub2e8\ud574 \ubcf4\uc600\ub2e4.":97,[u.bJ]:98,"\uc7a1\uc74c \uc0ac\uc774\ub85c \ubaa9\uc18c\ub9ac\uac00 \ub4e4\ub838\ub2e4. \u201c\u2026\ubc1c\uc804\uc18c\u2026 \uc544\uc9c1\u2026 \ub204\uad6c \uc5c6\ub098\u2026\u201d":99,"\uc0b4\uc544\ub0a8\uc740 \uac74 \uc6b0\ub9ac\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4.":100,"\uc774\uc81c \ubc29\uc1a1\uc740 \uc5ec\uae30\uc11c \ud560\uac8c\uc694. \ubb34\uc804\uc2e4 \uc548\ud14c\ub098\uba74 \ud6e8\uc52c \uba40\ub9ac\uae4c\uc9c0 \ub2ff\uc744 \uac70\uc608\uc694.":101,[u.bH]:102,"\ubc1c\uc804\uc18c\uae4c\uc9c0 \ub2ff\uc744 \ub9cc\ud07c \ubc1d\uc73c\uba74\u2026 \ub204\uad70\uac00 \ub2f5\ud560\uc9c0\ub3c4 \ubab0\ub77c\uc694.":103,"\uc258\ud130\uc758 \ubd88\ube5b\uc774 \uad6c\ub984\uc744 \ub6ab\uace0 \uc9c0\ud3c9\uc120\uae4c\uc9c0 \ub2ff\uc558\ub2e4.":104,"\uba40\ub9ac \ubc1c\uc804\uc18c \ucabd\uc5d0\uc11c, \uc791\uc740 \ubd88\ube5b \ud558\ub098\uac00 \uae5c\ube61\uc774\uba70 \ub2f5\ud588\ub2e4.":105,"\uc0ac\ud758 \ub3d9\uc548, \ubc1c\uc804\uc18c \ucabd \ubd88\ube5b\uc774 \uc258\ud130 \ubd88\ube5b\uc5d0 \uac19\uc740 \ubc15\uc790\ub85c \ub2f5\ud588\ub2e4.":106,[u.I]:107,[u.h]:108,"\u2026\uadf8 \uc804\ub0a0 \uc800\ub141\uc5d0\ub3c4 \uad6c\ub984\uc774 \uc774\uc0c1\ud588\uc5b4\uc694. \uadf8\ub7f0\ub370 \ub9d1\ub2e4\uace0\ub9cc \ud558\ub77c\uace0 \ud574\uc11c.":109,[u.r]:110,"\uc774 \ubd88\ube5b\uc744 \ubcf4\uace0 \uc654\uc5b4\uc694. \uc774\uac78 \ud488\uace0\uc694.":111,"\ubbf8\uc601\uc774 \ud488\uc5d0\uc11c \uaebc\ub0b8 \uac83\uc740 \ud76c\ubbf8\ud558\uac8c \ube5b\ub098\ub294 \uae08\uc18d \uc6d0\ud1b5\uc774\uc5c8\ub2e4.":112,"\uc9c1\uc6d0\uc6a9 \ube44\uc0c1\uc2dd\ub7c9\uc73c\ub85c \ubc84\ud17c\uc5b4\uc694. \uc774 \ube5b\uc73c\ub85c \uc7ac\uc758 \ubcbd\uc744 \uac74\ub108\uc654\uace0\uc694.":113,"\uc2e4\ud5d8\ub85c\uc758 \uc2ec\uc9c0\uc608\uc694. \uaebc\ub0b4\ub294 \ub370\u2026 \uc624\ub798 \ub9dd\uc124\uc600\uc5b4\uc694.":114,"\ubc1b\uc544 \uc904 \uacf3\ub9cc \uc788\uc73c\uba74 \ub3fc\uc694. \uc774\ubc88\uc5d4 \uc81c\ub300\ub85c.":115,"\ubbf8\uc601\uc740 \ub098\ub97c \ud55c\ucc38 \ubcf4\ub2e4\uac00, \ubb34\uc5b8\uac00 \ub9d0\ud558\ub824\ub358 \uc785\uc744 \ub2eb\uc558\ub2e4.":116,"\u2026\ubbf8\uc601 \uc528. \uc0b4\uc544 \uc788\uc5c8\uad70\uc694.":117,[u.J]:118,[u.a_]:119,[u.cG]:120,"\u2026\uc774 \uc124\uacc4\ub3c4, \uae30\uc5b5\ub098\uc694. \uc6d0\ub798\u2026 \ub2e4\ub978 \ubd84\uc774 \uadf8\ub9b0 \uac70\uc608\uc694.":121,"\ud658\uc601 \uc790\ub9ac\uc5d0 \uc740\ud638\ub9cc \ubcf4\uc774\uc9c0 \uc54a\uc558\ub2e4. \ubc29\uc1a1 \uc900\ube44 \uc911\uc774\ub77c\uace0 \ud588\ub2e4.":122,[u.b1]:123,[u.l]:124,"\uc124\uacc4\ub3c4\ub294 \ubbf8\uc601 \uc528\uac00 \uc9c0\ucf1c \uc654\uc5b4\uc694. \uc313\ub294 \uac74\u2026 \ubaa8\ub450\uc758 \ubaab\uc774\uc5d0\uc694.":125,"\ud1a0\ub300\uc5d0 \ubaa8\ub450\uc758 \uc774\ub984\uc744 \uc0c8\uacbc\ub2e4. \uc544\uc774\ub4e4 \uc774\ub984\ub3c4.":126,"\uae30\ub465\uc740 \ubbff\uc744 \uc218 \uc788\ub294 \uc190\ub4e4\uc774 \ubd99\uc7a1\uc544\uc57c \ud574. \uc11c\ub85c \ubbff\ub294 \uc0ac\ub78c\ub4e4 \ub9d0\uc774\uc57c.":127,"\uadf8\ub54c \uac10\uc2f8 \uc918\uc11c\u2026 \uace0\ub9c8\uc6e0\uc5b4\uc694. \uc774\ubc88 \uae30\ub465\uc740 \uc81c\uac00 \uc81c\uc77c \uba3c\uc800 \ubd99\uc7a1\uc744\uac8c\uc694.":128,"\ub9d0\ubcf4\ub2e4 \uc190\uc73c\ub85c \uac1a\uaca0\ub2e4\uace0 \ud588\uc8e0. \uae30\ub465 \uc6a9\uc811\uc740 \uc81c\uac00 \ubc24\uc0c8 \ud574 \ub458\uac8c\uc694.":129,"\ucca0\uace8\uc774 \ud558\ub298\ub85c \ubed7\uc5c8\ub2e4. \uba40\ub9ac\uc11c\ub3c4 \ubcf4\uc77c \ub9cc\ud07c.":130,[u.Z]:131,"\uc804\uc120\uc5d0 \uc190\uc744 \ub300\ub2c8 \ubbf8\uc138\ud558\uac8c \ub5a8\ub838\ub2e4. \uc0b4\uc544 \uc788\ub294 \uac83\ucc98\ub7fc.":132,"\uc774 \ub80c\uc988\uac00 \ube5b\uc744 \ubaa8\uc544\uc694. \uadf8\ub7f0\ub370\u2026 \uadf8 \ub79c\ud134, \uc7a0\uae50 \ubcf4\uc5ec \uc904\ub798\uc694?":133,"\uc5ed\uc2dc. \ub4f1\ubd88 \uacc4\ud68d \uccab \uc2dc\uc81c\ud488, LP-001\uc774\uc5d0\uc694.":134,[u.f]:135,"\u2026\uc774 \ub79c\ud134, \ub204\uad6c\ud55c\ud14c \ubc1b\uc558\uc5b4\uc694?":136,"\uc544\ubc84\uc9c0\uac00 \uadf8\ub0a0 \ubc24 \ub9e1\uae30\uace0 \uac04 \uac70\ub77c\uace0 \ub2f5\ud588\ub2e4.":137,"\u2026\uadf8\ub807\uad70\uc694.":138,"\ubbf8\uc601\uc740 \ub354 \ubb3b\uc9c0 \uc54a\uc558\ub2e4. \ub300\uc2e0 \ub79c\ud134 \ubc11\ubc14\ub2e5\uc758 \uc77c\ub828\ubc88\ud638\ub97c \ud55c\ucc38 \ub4e4\uc5ec\ub2e4\ubd24\ub2e4.":139,[u._]:140,"\ucc98\uc74c\ubd80\ud130 \ub4e4\uace0 \uc788\ub358 \uc774 \ub79c\ud134\uc774, \ubaa8\ub4e0 \uc774\uc57c\uae30\uc758 \uc2dc\uc791\uc774\uc5c8\ub2e4.":141,"\ubaa8\ub450\uac00 \ud0d1 \uc544\ub798 \ubaa8\uc600\ub2e4. \ub204\uad70\uac00\ub294 \uc6b8\uace0, \ub204\uad70\uac00\ub294 \uc6c3\uc5c8\ub2e4.":142,"\uc900\ube44\ub410\uc5b4\uc694. \uc2ec\uc9c0\ub294\u2026 \ub4f1\ubd88\uc9c0\uae30\uc758 \ub79c\ud134\uc73c\ub85c \uae68\uc6cc \uc918\uc694.":143,"\uc791\uc740 \ud0dc\uc591\uc774 \ud070 \ud0dc\uc591\uc744 \uae68\uc6b0\ub294 \uac70\uc608\uc694.":144,"\ud0d1 \uaf2d\ub300\uae30\uc5d0 \uccab \ubd88\uc774 \ub4e4\uc5b4\uc654\ub2e4. \uc258\ud130 \uc704 \uad6c\ub984\uc774 \uc870\uae08 \uc605\uc5b4\uc84c\ub2e4.":145,"\uadf8\ub54c, \uc9c0\ud3c9\uc120 \ub108\uba38\uc5d0\uc11c \ubd88\ube5b \ud558\ub098\uac00 \uae5c\ube61\uc600\ub2e4. \uc6b0\ub9ac \ud0d1\uc774 \uc544\ub2c8\uc5c8\ub2e4.":146,"\u2026\ub2e4\ub978 \ubd84\uc18c\uc608\uc694. \ub4f1\ubd88 \uacc4\ud68d\uc740 \uc5ec\uae30 \ud558\ub098\uac00 \uc544\ub2c8\uc5c8\uc5b4\uc694.":147,"\uc544\uc9c1 \uc2dc\uc791\uc774\uc5d0\uc694. \ud0d1\uc774 \ub192\uc544\uc9c8\uc218\ub85d \ube5b\uc740 \ub354 \uba40\ub9ac \ub2ff\uc544\uc694.":148,"\ud55c \uce35\uc529, \ud55c \uce78\uc529. \uc6b0\ub9ac\ub294 \uacc4\uc18d \uc313\uc544 \uc62c\ub9ac\uae30\ub85c \ud588\ub2e4.":149,"\uc815\uc804\ub41c \uac70\ub9ac. \ubc1c\ubc11\uc870\ucc28 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4.":150,[u.c5]:151,"\ub450\ub4dc\ub9ac\uba74 \ube5b\uc774 \ubc88\uc9c4\ub2e4. \ub69c\uaed1\uc774 \ub2eb\ud790 \ub54c\ub9c8\ub2e4 \ub538\uae4d, \uc791\uc740 \uc18c\ub9ac\uac00 \ub09c\ub2e4.":152,"\uc544\uae4c \ub545\uc774 \ud06c\uac8c \ud754\ub4e4\ub838\ub2e4. \ubc1c\uc804\uc18c \ucabd\uc5d0\uc11c \uc6b0\ub974\ub989 \uc18c\ub9ac\uac00 \ub0ac\ub2e4.":153,"\ubb34\ub108\uc9c4 \uc9d1\uc5d0\uc11c \uc4f8 \ub9cc\ud55c \uac78 \ucc59\uae30\uc790. \ub450\ub4dc\ub9ac\uba74 \ubb54\uac00 \ub098\uc628\ub2e4.":154,"\uacf5\ud130\uc5d0 \ud150\ud2b8\ub97c \ucce4\ub2e4. \uc4f0\ub7ec\uc9c4 \uc288\ud37c \uac04\ud310 \uc67c\ud3b8. \uc624\ub298 \ubc24\uc740 \uc5ec\uae30\uc11c \ubc84\ud2f4\ub2e4.":155,"\ud150\ud2b8\ub97c \ub204\ub974\uba74 \ubb34\uc5c7\uc744 \uc9c0\uc744 \uc218 \uc788\ub294\uc9c0 \ubcfc \uc218 \uc788\ub2e4.":156,"\ubc88\uca4d. \ubc1c\uc804\uc18c \ucabd \ud558\ub298\uc774 \ud558\uc597\uac8c \ud0c0\uc62c\ub790\ub2e4.":157,"\uadf8\ub9ac\uace0, \uc7ac\uac00 \ub0b4\ub9ac\uae30 \uc2dc\uc791\ud588\ub2e4.":158,"\uc313\uc774\uae30 \uc804\uc5d0 \ub450\ub4dc\ub824 \uac77\uc5b4\ub0b4\uc790!":159,"\ub77c\ub514\uc624\uc5d0\uc11c\ub294 \uc2ec\uc57c \ubc29\uc1a1\uc774 \ud750\ub974\uace0 \uc788\uc5c8\ub2e4. \ub204\uad70\uac00 \uc2e0\uccad\ud55c \uc61b \ub178\ub798.":160,"\uc7ac\ub294 \ubc24\uc0c8 \uadf8\uce58\uc9c0 \uc54a\uc558\ub2e4.":161,"\uadf8\ub0a0 \ubc24\uc5d0\ub3c4 \uc2ec\uc57c \ubc29\uc1a1\uc774 \ud758\ub800\ub2e4.":162,"\ubaa8\ub798 \uba3c\uc9c0 \uc18d\uc5d0 \ub179\uc2a8 \uae09\uc720\ud0d1\uc774 \uc904\uc9c0\uc5b4 \uc11c \uc788\ub2e4. \ud488\uc5d0 \uc548\uc740 \ubd88\uc528 \uc0c1\uc790\uac00 \uc544\uc9c1 \ub530\ub73b\ud558\ub2e4.":163,"\uc6b0\uc120 \uc6b0\ub9ac \uc790\ub9ac\ubd80\ud130 \ubc1d\ud788\uc790\uace0. \uc2e0\ud638 \ubcf4\ub0b8 \uc0ac\ub78c\uc774 \uc5b4\ub518\uac00 \uc788\uc744 \uac70\uc57c.":164,"\uc815\ub9d0 \uc654\uad6c\uba3c! \ubd88\ube5b \ubcf4\uace0 \ub6f0\uc5b4\ub098\uc654\uc18c. \ub0b4\uac00 \ub77c\ub514\uc624\ub85c \ubd80\ub978 \uae09\uc720\ud0d1\uc9c0\uae30 \ub450\uc2dd\uc774\uc624.":165,"\uc800 \uae09\uc720\ud0d1 \uaf2d\ub300\uae30 \ubd88? \uc6b0\ub9ac\uac00 \ucf20 \uac8c \uc544\ub2c8\uc624. \uc6d0\ub798\ubd80\ud130 \uac00\ub054, \ud63c\uc790 \ucf1c\uc84c\uc9c0.":166,"\uc5ec\uae34 \ubb3c\uc774 \uadc0\ud574. \ub300\uc2e0 \uae30\ub984\uc740 \ub118\uce5c\ub2e4\uc624. \ubd88\uc774 \uaebc\uc9c8 \uac71\uc815\uc740 \uc5c6\uc744 \uac70\uc694.":167,"\ub450 \ubc88\uc9f8 \ud310\uc7a3\uc9d1. \ucc98\uc74c\ubcf4\ub2e4 \uc190\uc774 \ud6e8\uc52c \ube68\ub790\ub2e4.":168,"\ub9c8\uc744 \uc0ac\ub78c\ub4e4\uc774 \uae09\uc720\ud0d1 \ubc11 \uc9c0\ud558 \ud0f1\ud06c\uc5d0 \uc228\uc5b4 \uc788\uc18c. \uc5f0\ub8cc\ub97c \ubaa8\uc544 \ubd88\uc744 \ubc1d\ud600 \uc8fc\uba74 \ub098\uc62c \uac70\uc694.":169,"\u2026\uc800\uae30 \ubd10\uc694. \uc0ac\ub78c\ub4e4\uc774 \ud558\ub098\ub458 \uc62c\ub77c\uc624\uace0 \uc788\uc5b4.":170,"\uc0ac\ub9c9\uc5d0 \ubb3c\uc774 \uc5c6\ub2e4\ub294 \uac74\u2026 \ubc18\uc740 \uac70\uc9d3\ub9d0\uc774\uc624.":171,"\uae09\uc720\ud0d1 \ubc11 \uc5b4\ub518\uac00\uc5d0 \uc800\uc218\uc870\uac00 \uc788\uc18c. \ub2e4\ub4e4 \uc11c\ub85c \ubabb \ubbff\uc5b4\uc11c \uc228\uaca8 \ubc84\ub838\uc9c0.":172,"\ubaa8\ub798 \ubc11 \ucca0\ubb38\uc744 \uc5f4\uc790, \uc11c\ub298\ud55c \ubb3c \ub0c4\uc0c8\uac00 \uc62c\ub77c\uc654\ub2e4.":173,"\u2026\uadf8\ub798, \uc774\uac70\uc694. \ub9c8\uc744 \uc0ac\ub78c\ub4e4\uc774 \uc228\uaca8 \ub454 \uc800\uc218\uc870.":174,"\ubb3c\uc774 \uc788\ub2e4\ub294 \uc18c\ubb38\uc740 \uae08\ubc29 \ud37c\uc9c0\uc624. \uc624\ub298 \ubc24, \ubb3c \ub3c4\ub451\ub4e4\uc774 \uc62c \uac70\uc694.":175,"\ub9c9\uc544 \ub0c8\uad6c\uba3c. \u2026\uadf8 \ub3c4\ub451\ub4e4\ub3c4 \ubaa9\uc774 \ub9d0\ub790\uc744 \ubfd0\uc774\uc624.":176,"\uc774 \ubb3c\uc744 \uc5b4\ub5bb\uac8c \ud560\uc9c0, \ub2f9\uc2e0\uc774 \uc815\ud574 \uc8fc\uc2dc\uc624.":177,"\uc774 \ubb3c\uc774\uba74 \uc57d\ucd08\ubc2d\uc744 \uc0b4\ub9b4 \uc218 \uc788\uc5b4\uc694.":178,"\uacb0\uc815\uc740 \ub0b4\ub824\uc84c\ub2e4. \uc0ac\ub9c9\uc758 \ubc24\uc774 \uc870\uae08 \ub35c \ubaa9\ub9c8\ub974\ub2e4.":179,"\uc5ec\uae30 \uc0ac\ub78c\ub4e4\uae4c\uc9c0 \uc9c0\ud0a4\ub824\uba74 \ub354 \ud2bc\ud2bc\ud574\uc57c \ud574.":180,"\uc774 \ubaa8\ub798 \ub3c4\uc2dc\uc5d0 \ubcbd\uc774 \uc120 \uac74 \ucc98\uc74c\uc774\uc624.":181,"\uc5ec\uae30\uc11c\ub3c4 \ud0d1\uc744 \uc138\uc6b8 \uc218 \uc788\uc5b4\uc694. \uac00\uc838\uc628 \ubd88\uc528\uba74 \ucda9\ubd84\ud574\uc694.":182,"\uac00\uc838\uc628 \ubd88\uc528\uba74 \ucda9\ubd84\ud558\ub2e4. \uc5ec\uae30\uc11c\ub3c4 \ud0d1\uc744 \uc138\uc6b8 \uc218 \uc788\ub2e4.":183,"\uc0ac\ub9c9 \ud55c\uac00\uc6b4\ub370, \ub450 \ubc88\uc9f8 \ubd88\ube5b\uc758 \ub3c4\uc2dc\uac00 \uc130\ub2e4.":184,"\uc6b0\ub9ac \uc190\uc8fc\ub4e4\ud55c\ud14c \ubcc4\uc744 \ubcf4\uc5ec \uc904 \uc218 \uc788\uc744\uae4c?":185,"\u2026\uace0\ub9d9\uc18c. \uc774 \ubd88\uc740 \uc774\uc81c \uc6b0\ub9ac\uac00 \uc9c0\ud0a4\uaca0\uc18c.":186,"\ubd88\uc528\ub294 \ub098\ub208\ub2e4\uace0 \uc904\uc9c0 \uc54a\ub294\ub2e4. \ub298\uc5b4\ub0a0 \ubfd0\uc774\ub2e4.":187,"\ud0d1\uc5d0 \ubd88\uc774 \ucf1c\uc9c4 \ub4a4\ub85c, \ub77c\ub514\uc624\uc5d0 \ucc98\uc74c \ub4e3\ub294 \ubaa9\uc18c\ub9ac\uac00 \uc11e\uc778\ub2e4.":188,"\u2026\uc5ec\uae30\ub294 \ub0a8\ucabd \uc0ac\ub9c9, \uae09\uc720\ud0d1 \ub9c8\uc744. \ubb3c\ub3c4 \ubd88\ub3c4 \ub2e4 \ub5a8\uc5b4\uc838 \uac00\uc694. \uadf8\ucabd \ubd88\ube5b\u2026 \uc6b0\ub9ac\ud55c\ud14c\ub3c4 \ub098\ub220 \uc904 \uc218 \uc788\ub098\uc694?":189,"\uc2ec\uc9c0\uc758 \ubd88\uc528\ub294 \ub098\ub20c \uc218 \uc788\uc5b4\uc694. \ud0d1 \ud558\ub098 \uc138\uc6b8 \ub9cc\ud07c\uc740\uc694.":190,"\uc2ec\uc9c0\uc758 \ubd88\uc528\ub294 \ub098\ub20c \uc218 \uc788\ub2e4. \ud0d1 \ud558\ub098 \uc138\uc6b8 \ub9cc\ud07c\uc740.":191,"\ub5a0\ub0a0\uc9c0\ub294 \uc6b0\ub9ac\uac00 \uc815\ud55c\ub2e4. \uc900\ube44\uac00 \ub418\uba74, \ubd88\uc528\ub97c \ub4e4\uace0 \uac00\uc790.":192,"\u2026\ud5c8\ud5c8. \uc695\uc2ec \uc5c6\ub294 \uc0ac\ub78c\ub4e4\uc774\uad70. \uc774 \ub9c8\uc744\ub3c4 \ub2e4\uc2dc \uc6c3\uaca0\uc18c.":193,"\uad00\ub9ac\ud55c\ub2e4\ub77c\u2026 \uc2f8\uc6c0\uc740 \uc904\uaca0\uc9c0. \uc870\uae08 \uc12d\uc12d\ud558\uae34 \ud558\uc624\ub9cc.":194,"\uad74\ub69d\uc774 \uc232\ucc98\ub7fc \uc11c \uc788\ub294 \uacf5\ub2e8. \uc7ac\uac00 \uac00\uc7a5 \uc9d9\uac8c \uc313\uc778 \uacf3\uc774\ub2e4.":195,"\ubc24\uc774 \ubb34\uc11c\uc6b4 \uacf3\uc774\ub77c\ub354\uad70. \uc11c\ub458\ub7ec \ubd88\ube5b\ubd80\ud130 \ucf1c\uc790.":196,"\u2026\ube5b? \uc9c4\uc9dc \ube5b\uc774\ub124. \uacf5\ub2e8 \ubc18\uc7a5 \ub9c8\uc11d\uc774\ub2e4. \uc5ec\uae30\uc120 \ub2e4\ub4e4 \ubc24\ub9c8\ub2e4 \uc2f8\uc6b0\uc9c0.":197,"\uc7ac \uad34\ubb3c\uc774 \uc774\ud2c0\uc5d0 \ud55c \ubc88\uc529 \ubab0\ub824\uc628\ub2e4. \ubcbd\ubd80\ud130 \uc138\uc6cc.":198,"\ucca0\ud310\uc774 \ub118\uce58\ub294 \ub3d9\ub124\ub77c, \ud310\uc7a3\uc9d1 \uc808\ubc18\uc774 \uc1f3\ub369\uc774\ub2e4.":199,"\uc6b0\ub9ac\ub3c4 \uac19\uc774 \uc2f8\uc6b0\uaca0\ub2e4. \ub300\uc2e0 \ubc84\ud168 \ub0b4\ub294 \uac78 \ubcf4\uc5ec \uc918.":200,"\ub450 \ubc88\uc744 \ubc84\ud17c\uc5b4. \u2026\uc88b\uc544, \uc6b0\ub9ac\ub3c4 \ub108\ud76c\ub97c \ubbff\ub294\ub2e4.":201,"\uc774\uc0c1\ud558\uc9c0. \uacf5\ub2e8\uc740 \ub2e4 \uba48\ucdc4\ub294\ub370 3\uacf5\uc7a5 \uad74\ub69d\ub9cc \uc5f0\uae30\ub97c \ubfdc\uc5b4.":202,"\u2026\uc124\ub9c8.":203,"\ucff5, \ucff5. \uc544\ubb34\ub3c4 \uc5c6\ub294 \uacf5\uc7a5\uc5d0\uc11c \uae30\uacc4\uac00 \ub3cc\uc544\uac00\uace0 \uc788\uc5c8\ub2e4.":204,"\uc774\uac74\u2026 \uc81c\uac00 \uc124\uacc4\ud55c \ub4f1\ubd88 \uacc4\ud68d \ubd80\ud488 \ub77c\uc778\uc774\uc5d0\uc694. \uc7ac\ub97c \ubfdc\uc73c\uba74\uc11c \uc544\uc9c1\ub3c4 \ub3cc\uace0 \uc788\uc5b4\uc694.":205,"\uc7ac\ud601\uc774 \ubcf4\uc5ec \uc900 \ub3c4\uba74\uc774 \ub5a0\uc62c\ub790\ub2e4. \ub4f1\ubd88 \uacc4\ud68d \ubd80\ud488 \ub77c\uc778. \uc7ac\ub97c \ubfdc\uc73c\uba70 \uc544\uc9c1\ub3c4 \ub3cc\uace0 \uc788\uc5c8\ub2e4.":206,"\ub124\uac00 \uc124\uacc4\ud588\ub2e4\uace0? \u2026\uc88b\uc544. \uadf8\ub7fc \ub044\ub294 \uac83\ub3c4 \ub124 \ubaab\uc774\ub2e4.":207,"\uc800 \ub77c\uc778\uc744 \uba48\ucdb0\uc57c \ud55c\ub2e4. \uc815\ubb38, \ubc30\uad00, \ub9c8\uc9c0\ub9c9 \uc2a4\uc704\uce58. \ub108\ud76c \uc190\uc744 \ube4c\ub9ac\uaca0\ub2e4.":208,"\ubb38\uc740 \ub0b4\uac00 \uc6a9\uc811\ud574\uc11c \ub6ab\uc9c0.":209,"\ub9c8\uc9c0\ub9c9 \uc2a4\uc704\uce58\uac00 \ub0b4\ub824\uac00\uc790, \uacf5\ub2e8\uc774 \ucc98\uc74c\uc73c\ub85c \uc870\uc6a9\ud574\uc84c\ub2e4.":210,"\u2026\uace0\ub9d9\ub2e4. \uadf8\ub9ac\uace0, \ubbf8\uc548\ud588\ub2e4.":211,"\uc774\uc81c \uc800 \ub77c\uc778\uc744 \uc5b4\ub5bb\uac8c \ud560 \uac70\ub0d0.":212,"\ubd80\uc218\ub294 \uac8c \ub9de\uc744\uc9c0\ub3c4 \ubab0\ub77c\uc694. \ud558\uc9c0\ub9cc \uace0\uce58\uba74\u2026 \uc0ac\ub78c\uc744 \uc704\ud55c \uac78 \ub9cc\ub4e4 \uc218 \uc788\uc5b4\uc694.":213,"\ubd80\uc218\uba74 \uc7ac\uac00 \uc904\uc5b4\ub4e0\ub2e4. \uace0\uce58\uba74\u2026 \uc0ac\ub78c\uc744 \uc704\ud55c \uac78 \ub9cc\ub4e4 \uc218\ub3c4 \uc788\ub2e4.":214,"\uacf5\ub2e8\uc758 \uad74\ub69d \ud558\ub098\uac00, \ub2e4\ub978 \uc774\uc720\ub85c \uc5f0\uae30\ub97c \ub0b4\uae30 \uc2dc\uc791\ud588\ub2e4.":215,"\uc5ec\uae30\uc11c \ub9cc\ub4e0 \ub80c\uc988\uac00 \ub2e4\ub978 \ubd84\uc18c\ub85c\ub3c4 \uac14\uc5b4\uc694. \uba87 \uacf3\uc774\ub098 \ub418\ub294\uc9c0\ub294\u2026 \uc800\ub3c4 \ubab0\ub77c\uc694.":216,"\uc774 \uacf5\ub2e8\uc5d0\uc11c \ub9cc\ub4e0 \ub80c\uc988\uac00 \ub2e4\ub978 \ubd84\uc18c\ub85c\ub3c4 \uac14\ub2e4\uace0 \ud55c\ub2e4. \uba87 \uacf3\uc778\uc9c0\ub294 \uc544\ubb34\ub3c4 \ubaa8\ub978\ub2e4.":217,"\uadf8 \uacc4\ud68d \ub54c\ubb38\uc5d0 \uc7ac\uac00 \uc654\ub2e4\ub294 \uac74 \ub4e4\uc5c8\ub2e4. \uadf8\ub798\ub3c4 \ubd88\uc744 \ub4e4\uace0 \uc628 \uac74 \ub108\ud76c\ub2e4.":218,"\uc5ec\uae30 \uc0ac\ub78c\ub4e4 \uc190\uc7ac\uc8fc\uba74 \ud0d1\ub3c4 \uae08\ubc29 \uc62c\ub77c\uac00\uaca0\uad6c\uba3c.":219,"\uad74\ub69d \uc0ac\uc774\ub85c \ud0d1\uc758 \ubf08\ub300\uac00 \uc62c\ub77c\uac04\ub2e4.":220,"\uc1e0 \ub450\ub4dc\ub9ac\ub294 \uc18c\ub9ac\uac00 \uc624\ub298\uc740 \ud558\ub098\ub3c4 \uc548 \ubb34\uc12d\uad70.":221,"\ube5b\uc774\ub2e4. \uc6b0\ub9ac \uacf5\ub2e8\uc5d0\ub3c4.":222,"\uc774 \ubd88\uc740 \ub9c8\uc11d\uc774 \uc9c0\ud0a4\uae30\ub85c \ud588\ub2e4.":223,"\uc0ac\ub9c9 \ud0d1\uc758 \ube5b\uc774 \ubd81\ucabd \ud558\ub298\uae4c\uc9c0 \ubc88\uc84c\ub2e4. \uadf8\ub0a0 \ubc24, \uac70\uce5c \ubaa9\uc18c\ub9ac\uac00 \ubb34\uc804\uc744 \ub450\ub4dc\ub838\ub2e4.":224,"\u2026\uc5ec\uae30\ub294 \ubd81\ucabd \uacf5\ub2e8. \uc7ac \uad34\ubb3c\uc774 \ub05d\uc774 \uc5c6\ub2e4. \uadf8 \uc0ac\ub9c9 \ubd88\ube5b, \uc5ec\uae30\uc11c\ub3c4 \ubcf4\uc778\ub2e4. \ub3c4\uc640\uc904 \uc218 \uc788\ub098.":225,"\uc774\ubc88\uc5d0\ub3c4 \ub5a0\ub0a0\uc9c0\ub294 \uc6b0\ub9ac\uac00 \uc815\ud55c\ub2e4. \ubd88\uc528\ub294 \ub109\ub109\ud558\ub2e4.":226,"\uc798\ud588\ub2e4. \uc774\uc81c \ubc24\uc5d0 \uc880 \uc798 \uc218 \uc788\uaca0\uad70.":227,"\u2026\ub124. \uc774\uac8c \ub9de\uc544\uc694.":228,"\uace0\ub9c8\uc6cc\uc694. \uc774\ubc88\uc5d4 \uc0ac\ub78c\uc744 \uc0b4\ub9ac\ub294 \uac78 \ub9cc\ub4e4\uac8c\uc694.":229,"\ub450\uace0 \ubcf4\uaca0\ub2e4. \ud558\uc9c0\ub9cc\u2026 \uae30\ub300\ub294 \ud558\uc9c0.":230,"\uc7ac \uc704\uc5d0 \ub208\uc774 \ub0b4\ub824 \uc628 \uc138\uc0c1\uc774 \uc7bf\ube5b \ub208\ubc2d\uc774\ub2e4.":231,"\ucd94\uc704\uac00 \uc81c\uc77c \ubb34\uc11c\uc6cc. \ubd88\ubd80\ud130 \ucf1c\uc790.":232,"\uc5b4\uba38, \ubd88\ube5b\uc774\ub2e4! \uc598\ub4e4\uc544! \u2026\uc0b0\uace8 \ubd84\uad50 \uc120\uc0dd \uc740\uc194\uc774\uc5d0\uc694.":233,"\ubd84\uad50 \uc544\uc774\ub4e4 \uc5f4\ub458\uc774 \uad50\uc2e4 \ub09c\ub85c \ud558\ub098\ub85c \ubc84\ud2f0\uace0 \uc788\uc5b4\uc694.":234,"\ud310\uc7a3\uc9d1 \ub09c\ub85c \uc606\uc5d0 \uc791\uc740 \uc2e0\ubc1c\ub4e4\uc774 \uc904\uc9c0\uc5b4 \ub193\uc600\ub2e4.":235,"\uc7a5\uc791\ub9cc \uc788\uc73c\uba74 \uaca8\uc6b8\uc744 \ub0a0 \uc218 \uc788\uc5b4\uc694. \uc232\uc740 \uc544\uc9c1 \ub0a8\uc544 \uc788\uc5b4\uc694.":236,"\uc7a5\uc791 \ud0c0\ub294 \ub0c4\uc0c8, \uc544\uc774\ub4e4 \uc6c3\uc74c\uc18c\ub9ac. \uc815\ub9d0 \uc624\ub79c\ub9cc\uc774\uc5d0\uc694.":237,"\ubd84\uad50\ub294 \uc0b0 \uc911\ud131\uc5d0 \uc788\uc5b4\uc694. \uc544\uc774\ub4e4\uc774 \uac70\uae30\uc11c \uae30\ub2e4\ub824\uc694.":238,"\uc598\ub4e4\uc544, \ubd88\ube5b \uc544\uc800\uc528\ub4e4\uc774\uc57c!":239,"\ud558\ub298 \uc0c9\uc774 \uc774\uc0c1\ud574\uc694. \uc0ac\ud758 \ub3d9\uc548 \uc9c0\ub3c5\ud55c \ud55c\ud30c\uac00 \uc62c \uac70\uc608\uc694.":240,"\ud558\ub298 \uc0c9\uc774 \uc774\uc0c1\ud574\uc694. \uc0ac\ud758 \ub3d9\uc548 \uc9c0\ub3c5\ud55c \ud55c\ud30c\uac00 \uc62c \uac83 \uac19\uc544\uc694.":241,"\uc7a5\uc791\uc774\u2026 \ubaa8\uc790\ub784\uc9c0\ub3c4 \ubab0\ub77c\uc694.":242,"\uc0ac\ud758\uc9f8 \uc0c8\ubcbd, \ucc3d\ubb38\uc758 \uc131\uc5d0\uac00 \ub179\uae30 \uc2dc\uc791\ud588\ub2e4.":243,"\uc0b0 \ub108\uba38 \ub300\ud53c\uc18c\uc5d0 \uc57d\uc774\ub791 \uc7a5\uc791\uc774 \ub0a8\uc544 \uc788\uc5b4\uc694. \ud558\uc9c0\ub9cc \ub208\uc0ac\ud0dc\uac00 \ub09c \uae38\uc774\uc5d0\uc694.":244,"\uc544\uc774\ub4e4\uc744 \uc0dd\uac01\ud558\uba74\u2026 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud560\uae4c\uc694.":245,"\ub208 \ub36e\uc778 \uc0b0\uace8\uc5d0\ub3c4 \ubd04\uc774 \uc62c \uac83 \uac19\ub2e4.":246,"\uc120\uc0dd\ub2d8, \uc800\ub3c4 \uc5ec\uae30 \uc560\ub4e4\uc774\ub791 \uac19\uc774 \uacf5\ubd80\ud574\ub3c4 \ub3fc\uc694?":247,"\uc258\ud130 \uc544\uc774\ub4e4\uc774 \ubd84\uad50 \uc544\uc774\ub4e4 \ud2c8\uc5d0 \uae08\uc138 \uc11e\uc5ec \uc549\uc558\ub2e4.":248,"\uad50\uc2e4\uc774 \uc870\uae08 \uc881\uc544\uc84c\ub124\uc694. \uc88b\uc740 \ucabd\uc73c\ub85c\uc694.":249,"\ub208 \uc18d\uc5d0\uc11c\ub3c4 \ube5b\ub098\ub294 \ub3c4\uc2dc\ub97c \ub9cc\ub4e4\uc5b4 \ubcf4\uc790\uace0.":250,"\ub208\ubc2d \uc704\ub85c \ubd88\ube5b\uc774 \ubc88\uc838, \ub9c8\uc744 \uc804\uccb4\uac00 \uae08\ube5b\uc774 \ub410\ub2e4.":251,"\uc544\uc774\ub4e4\ud55c\ud14c \ubcc4 \uc774\uc57c\uae30\ub97c \ud574 \uc92c\uc5b4\uc694. \uc9c4\uc9dc\ub85c \ubcf4\uace0 \uc2f6\ub300\uc694.":252,"\ubcf4\uc5ec\uc694! \ubcc4\uc774 \ubcf4\uc5ec\uc694!":253,"\uc138 \ubc88\uc9f8 \ubd88\uc528. \uc774\uc81c \ubd88\ube5b\uc774 \ubd88\ube5b\uc744 \ubd80\ub978\ub2e4.":254,"\uacf5\ub2e8\uc758 \ubd88\ube5b\uc774 \uc0b0 \ub108\uba38\uae4c\uc9c0 \ub2ff\uc740 \ubaa8\uc591\uc774\ub2e4. \ub5a8\ub9ac\ub294 \ubaa9\uc18c\ub9ac\uac00 \uc7a1\ud614\ub2e4.":255,"\u2026\uc5ec\uae30 \uc0b0\uace8 \ubd84\uad50\uc608\uc694. \uc544\uc774\ub4e4\uc774 \ub108\ubb34 \ucd94\uc6cc\ud574\uc694. \uba40\ub9ac \ubd88\ube5b\uc774 \ubcf4\uc5ec\uc11c\uc694\u2026.":256,"\uc900\ube44\uac00 \ub418\uba74, \ub208 \ub36e\uc778 \uc0b0\uc73c\ub85c.":257,"\uae38\uc740 \uc81c\uac00 \uc54c\uc544\uc694. \ub2e4\ub140\uc62c\uac8c\uc694.":258,"\uad6c\uc870\ub300\uac00 \ub3cc\uc544\uc654\ub2e4. \uc370\ub9e4 \uac00\ub4dd \uc57d\uacfc \uc7a5\uc791\uc744 \uc2e3\uace0.":259,"\ubd04\uae4c\uc9c0 \uac19\uc774 \ubc84\ud168\uc694. \uc544\uc774 \ud558\ub098\uac00 \uc258\ud130\uc5d0 \ub0a8\uace0 \uc2f6\ub300\uc694.":260}
